const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const T = nextInt();

    const t = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        t[i] = nextInt();
    }

    const p = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        p[i] = nextInt();
    }

    const C = nextInt();
    const u = new Int32Array(C);
    for (let i = 0; i < C; i++) {
        u[i] = nextInt();
    }

    // Agrupar itens por tipo
    // Para economizar memória e tempo, usamos CSR (Compressed Sparse Row)
    const count = new Int32Array(T + 1);
    for (let i = 0; i < N; i++) {
        count[t[i]]++;
    }

    const head = new Int32Array(T + 2);
    for (let i = 1; i <= T; i++) {
        head[i + 1] = head[i] + count[i];
    }

    const cur = new Int32Array(head);
    const byType = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        const type = t[i];
        byType[cur[type]++] = i;
    }

    // Ordenar itens de cada tipo pelo preço p[i]
    for (let type = 1; type <= T; type++) {
        const start = head[type];
        const end = head[type + 1];
        if (end - start > 1) {
            const slice = [];
            for (let i = start; i < end; i++) {
                slice.push(byType[i]);
            }
            slice.sort((a, b) => p[a] - p[b]);
            for (let i = start; i < end; i++) {
                byType[i] = slice[i - start];
            }
        }
    }

    // Ponteiros para o próximo elemento não visitado de cada tipo
    const ptr = new Int32Array(head);

    // Min-Heap global para todos os N itens
    // Critério: menor p, menor t, menor id
    const heap = new Int32Array(N);
    let heapSize = N;
    for (let i = 0; i < N; i++) {
        heap[i] = i;
    }

    function compare(a, b) {
        if (p[a] !== p[b]) return p[a] - p[b];
        if (t[a] !== t[b]) return t[a] - t[b];
        return a - b;
    }

    // Heapify em O(N)
    for (let i = (heapSize >>> 1) - 1; i >= 0; i--) {
        let parent = i;
        const val = heap[parent];
        while ((parent << 1) + 1 < heapSize) {
            let left = (parent << 1) + 1;
            let right = left + 1;
            let best = left;
            if (right < heapSize && compare(heap[right], heap[left]) < 0) {
                best = right;
            }
            if (compare(heap[best], val) < 0) {
                heap[parent] = heap[best];
                parent = best;
            } else {
                break;
            }
        }
        heap[parent] = val;
    }

    function heapPop() {
        if (heapSize === 0) return -1;
        const root = heap[0];
        const last = heap[--heapSize];
        if (heapSize > 0) {
            let parent = 0;
            while ((parent << 1) + 1 < heapSize) {
                let left = (parent << 1) + 1;
                let right = left + 1;
                let best = left;
                if (right < heapSize && compare(heap[right], heap[left]) < 0) {
                    best = right;
                }
                if (compare(heap[best], last) < 0) {
                    heap[parent] = heap[best];
                    parent = best;
                } else {
                    break;
                }
            }
            heap[parent] = last;
        }
        return root;
    }

    const removed = new Uint8Array(N);
    let totalRevenue = 0n;

    for (let j = 0; j < C; j++) {
        const type = u[j];
        if (type === 0) {
            // Cliente indeciso
            while (heapSize > 0) {
                const item = heapPop();
                if (!removed[item]) {
                    removed[item] = 1;
                    totalRevenue += BigInt(p[item]);
                    break;
                }
            }
        } else {
            // Cliente decidido
            let pIndex = ptr[type];
            const end = head[type + 1];
            while (pIndex < end && removed[byType[pIndex]]) {
                pIndex++;
            }
            ptr[type] = pIndex;

            if (pIndex < end) {
                const item = byType[pIndex];
                removed[item] = 1;
                totalRevenue += BigInt(p[item]);
                ptr[type] = pIndex + 1;
            }
        }
    }

    console.log(totalRevenue.toString());
}

solve();
